insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('compliance', 'advanced', 'module', 'm01-a-claim-is-evidence', 1, 'Clause 7.2 of the ORASHI register has nothing recorded. A request sets it to Conformant and supplies an evidence reference, with no assessment date and no assessor. What does canSetClauseStatus answer?', '["It allows the status, because the evidence reference is what a conformity claim stands on.", "It refuses, in the same sentence it gives a Conformant request that carries nothing at all.", "It refuses with the shorter sentence asking only for the date and the assessor.", "It allows the status and lists 7.2 under missingEvidenceParts for the rest."]'::jsonb, 1, 'The digest prints REFUSED for Conformant with an evidence reference only, in the words it uses for Conformant with nothing else: name the evidence, the date it was assessed and who assessed it. The shorter sentence belongs to a Nonconformant request with no date.'),
  ('compliance', 'advanced', 'module', 'm01-a-claim-is-evidence', 2, 'Clause 7.2 has nothing recorded. Which of these requests on it does canSetClauseStatus ALLOW?', '["Compliant, which is a word the clause status vocabulary does not carry.", "Partially conformant, with nothing else recorded on the clause.", "Not applicable as its status, while its applicability still reads Applicable.", "Nonconformant, with the date it was assessed and the assessor."]'::jsonb, 3, 'Nonconformant with a date and an assessor: ALLOWED. Partially conformant with nothing else is refused and asks for evidence as well. Not applicable while the clause still reads Applicable is refused because the two fields move together. Compliant is not a clause status.'),
  ('compliance', 'advanced', 'module', 'm01-a-claim-is-evidence', 3, 'A request sets clause 7.2''s status to Not applicable while its applicability still reads Applicable. Which requirement stops it?', '["The applicability and the status are set together, or neither is.", "An excluded clause keeps its justification on record.", "Every verdict names the evidence, the date it was assessed and who assessed it before it stands.", "Not applicable is a word the clause vocabulary does not carry, so the status itself is refused."]'::jsonb, 0, 'The refusal reads: "A clause determined not applicable cannot also carry a conformity verdict. Set both together, or neither." The justification rule arises once both fields read Not applicable, and Not applicable is one of the five words in CLAUSE_STATUSES.'),
  ('compliance', 'advanced', 'module', 'm01-a-claim-is-evidence', 4, 'Both fields of a clause are set to Not applicable with no justification. Of the four refusals the digest prints for this request, which one cites a numbered clause of the standard?', '["The ISO 14001:2015 refusal, which cites §9.2 of the standard the ORASHI register is kept against.", "The ISO 45001:2018 refusal, which cites §4.3 in the same words the ISO 9001:2015 sentence uses.", "The ISO 9001:2015 refusal, which cites §4.3 of that standard.", "The no-standard refusal, which falls back to §4.3."]'::jsonb, 2, 'Only the ISO 9001:2015 sentence names §4.3. The ISO 14001:2015 and ISO 45001:2018 sentences name their standard in the engine''s own shape, and with no standard passed the sentence names none. All four are refusals.'),
  ('compliance', 'advanced', 'module', 'm01-a-claim-is-evidence', 5, 'The same Not applicable request, with no justification, is sent with no standard passed as the fourth argument. What comes back?', '["An allowed verdict, because without a standard there is no requirement left to justify.", "A refusal naming ISO 14001:2015, the standard of the register the clause sits in.", "A refusal that asks why the requirement does not apply and names no standard.", "A refusal saying the call is missing its standard, returned before any justification is read."]'::jsonb, 2, 'The digest prints: "Say why this requirement does not apply. A requirement determined not applicable keeps its justification on record." The verdict is the same refusal for all three standards and for none; only the wording follows the standard passed.'),
  ('compliance', 'advanced', 'module', 'm01-a-claim-is-evidence', 6, 'Asked to set clause 7.2 to Compliant, the gate answers "Compliant is not a clause status." Where does the word Compliant belong in this course?', '["In the clause register, as a Conformant claim''s word once evidenced.", "In the obligation register, where it is one of the complianceStatus words.", "In the readiness counts, as the count of conformant clauses.", "In the document library, as the state of a document in force."]'::jsonb, 1, 'complianceStatus.STATUS_SEVERITY carries Compliant. isoCompliance.CLAUSE_STATUSES holds Not assessed, Conformant, Partially conformant, Nonconformant and Not applicable, and the readiness count is named conformant. Each register is held to its own vocabulary.'),
  ('compliance', 'advanced', 'module', 'm01-a-claim-is-evidence', 7, 'Clause 5.2 reads Conformant, claims conformity true, evidence record false and assessed true. What does missingEvidenceParts print for it?', '["evidence reference", "evidence reference, the date assessed and the assessor", "nothing, because the row already reads assessed true", "no row, since it lists Nonconformant clauses only"]'::jsonb, 0, 'missingEvidenceParts covers each applicable clause that claims conformity without a complete record, and prints 5.2: evidence reference. Its assessed column reads true, so the date and the assessor are there.'),
  ('compliance', 'advanced', 'module', 'm01-a-claim-is-evidence', 8, 'Clause 6.1.3 reads Nonconformant, with evidence record false and assessed true. What does that row show about the gate?', '["The row could not have passed the gate, since every clause verdict needs an evidence reference.", "The row is the unevidenced claim the register summary counts, because its evidence record reads false.", "The row is waiting on an assessor, since assessed marks only the date.", "The verdict carries what the gate asks of it: a date and an assessor, with no evidence reference."]'::jsonb, 3, 'A Nonconformant status needs two of the three. Clause 6.1.3 reads claims conformity false, so it makes no claim, and the summary''s unevidenced claims 1 is clause 5.2.'),
  ('compliance', 'advanced', 'module', 'm01-a-claim-is-evidence', 9, 'Clause 4.3 reads Conformant and review overdue true on the same row at 2026-10-15. What do the two readings say together?', '["The Conformant verdict lapses to Not assessed once the clause''s next review date has passed.", "The status column prints Review overdue in place of Conformant until the review is recorded.", "The overdue flag is held back while the clause reads Conformant.", "The last verdict still stands, and it is due to be looked at again and has not been."]'::jsonb, 3, 'Clause 4.3''s next review, 2026-10-01, is -14 days from the as-of date. The status is the last verdict and the flag says its review is late; neither changes the other. Review overdue is a Document Control review state.'),
  ('compliance', 'advanced', 'module', 'm01-a-claim-is-evidence', 10, 'At 2026-10-15 clause 6.1.2''s next review is 2026-11-02, 18 days away. Which flags does the engine print for it?', '["review due soon true, and review overdue true", "review due soon true, and review overdue false", "review overdue true, and review due soon false", "both false, as the date is ahead of the as-of date"]'::jsonb, 1, '18 days sits inside the window isoCompliance.REVIEW_LEAD_DAYS sets, and the date is ahead of the as-of date. No ORASHI row reads true for both flags, and 6.1.2 is the one clause that reads review due soon true.'),
  ('compliance', 'advanced', 'module', 'm01-a-claim-is-evidence', 11, 'Clause 4.4, the excluded clause, has no next review date. What do its two review flags read?', '["review overdue true, because a review date that is missing is treated as one that has passed.", "review due soon true, because a missing date is read as falling inside the lead window.", "Both false, and 4.4 is left out of the clause review table.", "Neither prints, and the summary counts 4.4 among reviews overdue."]'::jsonb, 2, 'The register prints next review none, review overdue false and review due soon false for 4.4, whose applicability and status both read Not applicable, and the table of clause reviews against the as-of date lists the other 12 clauses without it. The summary''s reviews overdue 1 is clause 4.3.'),
  ('compliance', 'advanced', 'module', 'm01-a-claim-is-evidence', 12, 'The summary prints reviews overdue 1 and reviews due soon 1. Which of the two does the readiness list carry, and at which severity?', '["Only the overdue review, as the watch item \"1 clause review is past due.\"", "Both, as two watch items, one for each review flag.", "Only the overdue review, as a serious item.", "Neither, since readiness does not read clause reviews."]'::jsonb, 0, 'The list carries one watch item for reviews and none for clause 6.1.2''s review due soon. The serious item on clause 4.3 is its stale coverage, a separate question asked of the same row.'),
  ('compliance', 'advanced', 'module', 'm01-a-claim-is-evidence', 13, 'The register summary prints evidenced claims 9 and unevidenced claims 1. Which clause is the one unevidenced claim?', '["Clause 6.1.3, Compliance obligations", "Clause 5.2, Environmental policy", "Clause 7.2, Competence", "Clause 4.4, the excluded clause"]'::jsonb, 1, 'An unevidenced claim claims conformity without its evidence record. Clauses 6.1.3 and 7.2 both read evidence record false, and neither claims conformity; 4.4 is excluded. Only 5.2 reads claims conformity true beside evidence record false.'),
  ('compliance', 'advanced', 'module', 'm01-a-claim-is-evidence', 14, 'Partially conformant sits between Conformant and Nonconformant. Which of the two does it match on what canSetClauseStatus asks for?', '["Conformant: it is refused without evidence, a date and an assessor, in the same sentence.", "Nonconformant: a date and an assessor are enough, and no evidence reference is asked for.", "Neither: it needs an evidence reference alone, since a partial claim carries no assessment.", "Neither: it is refused unless the clause''s applicability is changed in the same request."]'::jsonb, 0, 'The digest prints Partially conformant, nothing else: REFUSED, with the sentence Conformant meets, and ALLOWED with evidence, a date and an assessor. Clause 6.1.2 reads Partially conformant with claims conformity, evidence record and assessed all true.'),
  ('compliance', 'advanced', 'module', 'm01-a-claim-is-evidence', 15, 'The readiness counts print evidenced 9 and conformant 9. Do the two counts cover the same nine clauses?', '["Yes. Every Conformant clause carries evidence, so the two counts are one set of clauses.", "No. The evidenced count takes in the excluded clause 4.4, which the conformant count leaves out.", "Yes. The evidenced count is taken over the Conformant clauses only, so it cannot differ.", "No. Clause 5.2 is Conformant without evidence, and clause 6.1.2 is evidenced without being Conformant."]'::jsonb, 3, 'Conformant rows: 4.1, 4.3, 5.2, 7.5.3, 8.1, 8.2, 9.1.1, 9.2 and 10.2. Evidence record true: the same list with 6.1.2 in place of 5.2, and 4.4 reads false. Two equal counts need not be one set, which is why a report quotes each as it prints.'),
  ('compliance', 'advanced', 'module', 'm02-independence', 1, 'A planned internal audit has clauses 8.1, 8.2, 9.1.1 and 9.2 in scope. Proposed as its lead auditor, u-kalu is refused. Which clauses does the refusal name?', '["9.1.1, the clause recorded against u-kalu in this scope", "8.1, 8.2 and 9.2, the clauses another auditor must take", "none by number, as the refusal cites ISO 19011 alone", "8.1 and 8.2, the two clauses u-kalu owns inside this audit''s scope"]'::jsonb, 3, '"The lead auditor owns clauses 8.1, 8.2 in this audit''s own scope." The refusal ends "Clauses named: 8.1, 8.2." Clause 9.1.1 is u-tari''s and 9.2 is u-nneka''s.'),
  ('compliance', 'advanced', 'module', 'm02-independence', 2, 'In the ORASHI register u-nneka owns clauses 4.1, 4.3, 4.4, 9.2 and 10.2. Proposed as lead for the same planned audit, u-nneka is refused naming 9.2 alone. Why only 9.2?', '["The check names only the clause whose next review falls soonest.", "The check reads this audit''s own scope, and 9.2 is the only one of the five inside it.", "The others read Conformant with evidence, so none is open to a verdict.", "The refusal names one clause per person refused."]'::jsonb, 1, 'The scope holds 8.1, 8.2, 9.1.1 and 9.2. u-nneka''s 4.1, 4.3, 4.4 and 10.2 sit outside it, so owning them raises nothing for this audit. The refusal says so in its own words: "in this audit''s own scope".'),
  ('compliance', 'advanced', 'module', 'm02-independence', 3, 'Which two ways out does the lead auditor refusal offer the person planning the audit?', '["Change the scope, or change the auditor.", "Change the clause owner in the register, or name an external auditor.", "Have somebody else on the audit record each result the lead owns.", "Record a justification for the owned clauses, or exclude them from the standard."]'::jsonb, 0, 'The refusal reads "so either the scope or the auditor has to change." Dropping 8.1 and 8.2 would clear u-kalu, and choosing u-chidi clears the whole audit. The engine names the clauses and leaves the choice to the planner.'),
  ('compliance', 'advanced', 'module', 'm02-independence', 4, 'u-kalu is on an audit led by u-chidi and moves to record the result for clause 8.1. What does canExamineClause answer?', '["ALLOWED, because the lead check cleared the audit when u-chidi was named.", "REFUSED, offering to change either the scope of the audit or the lead auditor named on it.", "REFUSED, telling u-kalu that somebody else on the audit has to record this result.", "ALLOWED, because the check applies to the lead alone."]'::jsonb, 2, '"You own clause 8.1. An auditor may not audit their own work (ISO 19011), so somebody else on the audit has to record this result." The scope-or-auditor remedy belongs to the lead check. u-chidi recording 8.1 is ALLOWED.'),
  ('compliance', 'advanced', 'module', 'm02-independence', 5, 'Which owner decision puts the independence check on every examiner, beyond the lead auditor?', '["AS15 Q4, through the coverage count", "AS15 Q5, through canExamineClause", "AS15 D1, through the document review task", "AS15 Q6, through the readiness list"]'::jsonb, 1, 'Q5 reads: every examiner is checked for independence, through canExamineClause. Q4 is the coverage rule, D1 keeps an author off their own review, and Q6 sets the certificate''s severity.'),
  ('compliance', 'advanced', 'module', 'm02-independence', 6, 'u-obinna owns clauses 5.2, 7.2 and 7.5.3, and none of the four in the planned audit''s scope. What does the digest print for u-obinna as its lead auditor?', '["ALLOWED, in the row printed for u-chidi.", "REFUSED, naming 7.2 as the clause u-obinna has left unassessed.", "REFUSED, because u-obinna owns the unevidenced claim on clause 5.2.", "No row at all, so no verdict is stated for u-obinna."]'::jsonb, 3, 'The five printed rows are u-chidi, u-kalu, u-nneka, u-tari and an external lead named in text. A verdict the digest does not print is one this course does not state, however likely it looks from the ownership table.'),
  ('compliance', 'advanced', 'module', 'm02-independence', 7, 'In the Audit & Findings Manager, auditIndependence refuses u-boma named as both lead auditor and auditee. Which name does that rule check the lead against?', '["The owner of each clause in the audit''s scope, one clause at a time", "The author of the revision under review, as Document Control does", "The auditee named on the audit, one person against one person", "Each person recording a result, through canExamineClause"]'::jsonb, 2, '"The lead auditor is also the auditee for this audit. An auditor may not audit their own area: name somebody else as one or the other." The sentence names no clause and no standard. u-kelechi leading with u-boma audited is ALLOWED.'),
  ('compliance', 'advanced', 'module', 'm02-independence', 8, 'Of the independence refusals printed for the three apps this course teaches, which cite ISO 19011?', '["The two from the ISO register, for a lead auditor and for an examiner.", "Every one of them, as each concerns who may judge another person''s work.", "Only the Audit & Findings Manager''s, as the audit app.", "Only Document Control''s, as ISO 19011 governs the review of documents."]'::jsonb, 0, 'Both isoCompliance refusals carry "An auditor may not audit their own work (ISO 19011)". auditIndependence says an auditor may not audit their own area and names no standard, and Document Control asks for somebody independent of the draft.'),
  ('compliance', 'advanced', 'module', 'm02-independence', 9, 'Of the three independence refusals in this course, why can only the ISO lead auditor refusal list more than one item?', '["A person can own several clauses in one scope, while an auditee and an author are each one name.", "The ISO refusal lists every clause in the scope, whoever owns it, so the planner sees the audit whole.", "Only the ISO module records who owns what, so the other two apps have nothing they could list.", "The other two refusals are cut short on screen, which shows only the first name refused."]'::jsonb, 0, 'The ISO check reads clause ownership, so u-kalu''s refusal names 8.1 and 8.2. The Audit & Findings Manager reads one auditee, and Document Control reads the author of one revision.'),
  ('compliance', 'advanced', 'module', 'm02-independence', 10, 'An external lead auditor named in text is ALLOWED by the ISO lead auditor check. What does that verdict establish?', '["That the auditor is independent of every clause in scope, as ISO 19011 requires.", "That the audit becomes a certification audit.", "That the employer was checked against suppliers.", "That the name owns no clause in this audit''s scope, and nothing more."]'::jsonb, 3, 'The check compares names held on the record, and an external name with no account matches none of u-nneka, u-obinna, u-tari or u-kalu. What that auditor''s independence rests on in fact stays with whoever appoints them.'),
  ('compliance', 'advanced', 'module', 'm02-independence', 11, 'An internal audit led by an external auditor named in text is reported. How does it stand for coverage beside ISA-2026-S01, the Closed Surveillance audit?', '["Neither counts, because each was led by somebody from outside the organization.", "It counts once reported, being Internal; ISA-2026-S01 does not count whatever its status.", "Both count, because both have reached a status on the coverage counting list.", "It counts only once it is Closed, while ISA-2026-S01 already counts as Closed."]'::jsonb, 1, 'The type of the audit decides coverage. ISA-2026-S01 reads counts towards coverage false, and the clause it examined, 6.1.2, reads never. The employer of the person leading an internal audit does not enter the count.'),
  ('compliance', 'advanced', 'module', 'm02-independence', 12, 'The lead auditor refusal and the canExamineClause refusal cite ISO 19011 in the same words. Which of these is a difference between the two?', '["In the standard cited, since the examiner refusal cites ISO 14001:2015 in place of ISO 19011.", "In the verdict, since the examiner check only warns where the lead auditor check refuses.", "In their first sentence: one names the lead auditor, the other says \"You\".", "In the clauses named, since the examiner refusal lists the whole scope after \"Clauses named:\"."]'::jsonb, 2, 'Both carry "An auditor may not audit their own work (ISO 19011)". The lead refusal opens "The lead auditor owns clauses 8.1, 8.2 in this audit''s own scope." and the examiner refusal opens "You own clause 8.1." Both are refusals of the request.'),
  ('compliance', 'advanced', 'module', 'm02-independence', 13, 'Which of the refusals printed for the planned audit carries no "Clauses named:" list?', '["u-kalu''s refusal as the proposed lead of the planned audit", "u-kalu''s refusal when recording clause 8.1", "u-tari''s refusal as lead auditor", "u-nneka''s refusal as lead auditor"]'::jsonb, 1, 'canExamineClause refuses u-kalu on 8.1 with "You own clause 8.1." and lists nothing after. Each lead auditor refusal ends "Clauses named:", with 8.1, 8.2 for u-kalu, 9.2 for u-nneka and 9.1.1 for u-tari.'),
  ('compliance', 'advanced', 'module', 'm02-independence', 14, 'Why is the lead auditor check on its own not enough to keep an owner from examining their own clause?', '["An independent lead says nothing about the rest of the team, and any of them may record a result.", "The lead check reads only clauses outside the scope, so owners inside it pass unseen.", "The lead check runs once the audit is Reported, after the results are already recorded.", "The lead check reads the auditee and never reads the owners of the clauses in scope."]'::jsonb, 0, 'With u-chidi leading, the lead check reads ALLOWED, and u-kalu on the team could still record 8.1. canExamineClause closes that gap one result at a time, refusing u-kalu on 8.1 and allowing u-chidi.'),
  ('compliance', 'advanced', 'module', 'm02-independence', 15, 'Among the candidates for lead of the planned audit who hold an account, which one does the digest allow?', '["u-tari, whose one clause inside the audit''s scope is 9.1.1", "u-nneka, whose clause 9.2 is Conformant with evidence", "u-chidi, who owns none of the four clauses in scope", "u-kalu, once clauses 8.1 and 8.2 are recorded as Conformant"]'::jsonb, 2, 'u-chidi: ALLOWED. u-tari is refused naming 9.1.1, u-nneka naming 9.2 and u-kalu naming 8.1 and 8.2. A clause''s status plays no part in the check; ownership inside the scope is what it reads.'),
  ('compliance', 'advanced', 'module', 'm03-coverage-over-the-cycle', 1, 'ISA-2026-S01 is Closed, and Closed is one of the two counting statuses. Why does its row still read counts towards coverage false?', '["It ended after the latest internal audit.", "It examined a clause marked Partially conformant, which coverage leaves out.", "Its type is Surveillance, and COVERING_AUDIT_TYPES holds Internal alone.", "Its report came from the certification body and awaits the organization''s sign-off."]'::jsonb, 2, 'ISA-2026-S01 is a Surveillance audit, Closed, ended 2026-07-24, and the type alone keeps it out. The readiness list names the requirement: "ISO 14001:2015 §9.2 requires the organization to audit its own system."'),
  ('compliance', 'advanced', 'module', 'm03-coverage-over-the-cycle', 2, 'ISA-2026-S01 examined clause 6.1.2, Conformant on 2026-07-22. What does the coverage table print for clause 6.1.2?', '["last examined never, by audit none, covered false", "last examined 2026-07-22, by ISA-2026-S01, covered true", "last examined 2026-07-22, by ISA-2026-S01, stale true", "last examined never, by audit none, covered false and stale true"]'::jsonb, 0, 'Only counting audits compete to be a clause''s latest examination, and the one audit that examined 6.1.2 is of type Surveillance. 6.1.2 is one of the 3 applicable clauses never examined, and a never examined clause reads stale false.'),
  ('compliance', 'advanced', 'module', 'm03-coverage-over-the-cycle', 3, 'ISA-2026-002 is In progress and has examined clause 5.2, Conformant on 2026-10-06. What is clause 5.2''s last examined date in the coverage table?', '["2026-10-06, from ISA-2026-002, with the result Conformant", "2026-06-12, the date ISA-2026-001 ended", "never, as an audit in progress holds the clause open", "2026-06-09, from ISA-2026-001, with the result Observation"]'::jsonb, 3, 'An audit in progress is not a counting audit, so its results move no date until it is reported. Clause 5.2 keeps its latest counting examination, the Observation of 2026-06-09 by ISA-2026-001, and reads covered true.'),
  ('compliance', 'advanced', 'module', 'm03-coverage-over-the-cycle', 4, 'ISA-2025-003 examined clause 7.5.3 on 2025-11-12 and was then Cancelled. How does clause 7.5.3 read in the coverage table?', '["covered, since 2025-11-12 falls inside the certification cycle of 3 years", "never, and it is one of the 3 clauses never examined", "stale, since a cancelled audit''s examinations lapse", "covered until a cancellation reason is recorded"]'::jsonb, 1, 'A cancelled audit has no report and counts for nothing in coverage. ISA-2025-003 reads counts towards coverage false, so 7.5.3 reads never, beside 6.1.2 and 7.2.'),
  ('compliance', 'advanced', 'module', 'm03-coverage-over-the-cycle', 5, 'Clause 4.3 was last examined 2023-09-20 by ISA-2023-002, and clause 7.2 has never been examined. Which pair of flags does each read at a cycle of 3 years?', '["4.3 covered false and stale true; 7.2 covered false and stale true", "4.3 covered false and stale true; 7.2 covered false and stale false", "4.3 covered true and stale true; 7.2 covered false and stale false", "4.3 covered false and stale false; 7.2 covered false and stale true"]'::jsonb, 1, 'A clause can be stale only if it was once examined by a counting audit. 4.3 was, before the cycle began, at -1121 days. 7.2 has no counting examination, so it gets its own outcome, never, with stale false.'),
  ('compliance', 'advanced', 'module', 'm03-coverage-over-the-cycle', 6, 'Across the four cycle lengths the digest prints for the ORASHI register, which column never changes?', '["stale, at 3 in every row", "covered, at 8 in every row", "never examined, at 3 in every row", "never examined, falling to 0 at 4 years"]'::jsonb, 2, 'The cycle decides how far back an examination may fall and still count. It cannot create an examination that does not exist, so clauses 6.1.2, 7.2 and 7.5.3 read never at 1, 2, 3 and 4 years alike.'),
  ('compliance', 'advanced', 'module', 'm03-coverage-over-the-cycle', 7, 'The cycle moves from 3 years to 4 years and nothing else in the register changes. Which counts move?', '["covered goes from 8 to 9 and stale from 1 to 0, with never examined staying at 3.", "never examined goes from 3 to 0, and covered from 8 to 9, with stale left at 1.", "covered goes from 8 to 9 and never examined from 3 to 2, with stale left at 1.", "No count moves, because the cycle is fixed by the standard record itself."]'::jsonb, 0, 'The table prints cycleYears 3: covered 8, stale 1, never examined 3; and cycleYears 4: covered 9, stale 0, never examined 3. The cycle is an input to the call, so a different input gives different counts.'),
  ('compliance', 'advanced', 'module', 'm03-coverage-over-the-cycle', 8, 'At cycle lengths of 1 and 2 years the table prints the same pair, covered 6 and stale 3. What may a reader conclude from the two rows?', '["That the cycle has no effect below 3 years for any register at all.", "That the 3 stale clauses at those lengths are the 3 never examined.", "That 3 years is the shortest cycle the engine reads.", "Only that this register gives that pair at those two lengths."]'::jsonb, 3, 'The table shows this register at the four lengths printed and nothing more. Never examined also reads 3 at those lengths, a separate count from stale. Quote only the rows the digest prints.'),
  ('compliance', 'advanced', 'module', 'm03-coverage-over-the-cycle', 9, 'clauseCoverageByStandard reads ISO 14001:2015 clause 8.1 and ISO 45001:2018 clause 6.1.2, both last examined 2025-10-14. Why do they give two answers?', '["Each is read against its own standard''s cycle: 3 years and 1 year.", "Clause 6.1.2 was examined by a Surveillance audit and clause 8.1 by an internal one.", "The ISO 45001:2018 clause shares its number with ORASHI''s 6.1.2 and takes that clause''s reading.", "ISO 45001:2018 counts Closed audits only, where ISO 14001:2015 also counts Reported ones."]'::jsonb, 0, 'ISO 14001:2015 carries 3 years and 8.1 reads covered true; ISO 45001:2018 carries 1 year and 6.1.2 reads stale true. A clause number means something only beside its standard.'),
  ('compliance', 'advanced', 'module', 'm03-coverage-over-the-cycle', 10, 'Clause 10.2 reads last examined 2026-06-12, the date ISA-2026-001 ended, while clause 4.1 reads 2026-06-10 from the same audit. What is a clause''s last examined date?', '["The audit''s end date, moved earlier for any clause whose result arrived before the report.", "The date the result was entered into the register, taken from the assessor''s own record.", "The date it was examined within the audit, a field separate from the audit''s end.", "The audit''s planned end, offset for each clause by its place in the scope."]'::jsonb, 2, 'ISA-2026-001 ended 2026-06-12. Clause 10.2 was examined that day, and clauses 4.1, 5.2 and 6.1.3 on earlier ones: 2026-06-10, 2026-06-09 and 2026-06-11. Clause 4.3 shows the same, examined 2023-09-20 by an audit that ended 2023-09-22.'),
  ('compliance', 'advanced', 'module', 'm03-coverage-over-the-cycle', 11, 'Clause 6.1.3''s latest counting result is Nonconformant. How does it read for coverage?', '["covered false, since a Nonconformant result leaves the requirement unmet", "covered true, since coverage asks whether a counting audit examined it inside the cycle", "stale true, since a Nonconformant result needs a second examination", "covered true only once the finding it raised has been closed"]'::jsonb, 1, 'Clause 6.1.3 reads last examined 2026-06-11 by ISA-2026-001, Nonconformant, covered true. Clause 5.2''s Observation reads covered true as well. What the examiner found is the business of findings and of the register verdict.'),
  ('compliance', 'advanced', 'module', 'm03-coverage-over-the-cycle', 12, 'canReportAudit is called on ISA-2026-002, which has three clauses in scope and two not yet examined. What does it answer?', '["A refusal naming 5.2, the one clause the audit has examined so far", "ALLOWED, because an audit in progress may report the results it already holds", "A refusal saying the audit has no clauses in its scope to report on", "A refusal naming 7.2 and 8.1 as the two clauses in scope with no result yet"]'::jsonb, 3, 'The digest prints: "2 clauses in scope have no result yet (7.2, 8.1)." The sentence about an audit with no clauses in its scope belongs to an empty scope, a separate row.'),
  ('compliance', 'advanced', 'module', 'm03-coverage-over-the-cycle', 13, 'What has to happen, in order, before ISA-2026-002 can move any clause''s last examined date?', '["The audit is reported first, and then each clause''s result is entered against the report.", "The audit is Closed, since Reported leaves it uncounted.", "Every clause in its scope gets a result, and then the audit is reported.", "The audit is cancelled with a reason, which keeps its results."]'::jsonb, 2, 'canReportAudit refuses while a clause in scope has no result, and coverage counts only Reported or Closed audits. Until then clause 8.1 keeps 2024-05-16 from ISA-2024-001.'),
  ('compliance', 'advanced', 'module', 'm03-coverage-over-the-cycle', 14, 'Clause 7.5.3 reads Conformant with claims conformity, evidence record and assessed all true, and reads never in the coverage table. What do the two readings say together?', '["The organization says it conforms, and no counting internal audit has checked that it does.", "The coverage table overrides the register, so the clause''s status falls back to Not assessed.", "The coverage row is a display fault, since an evidenced verdict counts as an examination.", "The clause is covered for the cycle, since evidence dated inside it stands in for an internal audit."]'::jsonb, 0, 'The register verdict is the owner''s assessment, evidenced, dated and named. Coverage asks whether an internal audit examined the clause, which is what ISO 14001:2015 §9.2 asks for. Both statements are on the record at once.'),
  ('compliance', 'advanced', 'module', 'm03-coverage-over-the-cycle', 15, 'isoCompliance.COVERAGE_COUNTING_STATUSES holds two words. Which are they?', '["Fieldwork complete and Reported", "Reported and Closed", "In progress and Closed", "Closed and Cancelled"]'::jsonb, 1, 'Owner decision AS15 Q4 states it: ISO coverage counts only Reported or Closed audits. The three audits that count are ISA-2023-002 and ISA-2024-001, Closed, and ISA-2026-001, Reported.'),
  ('compliance', 'advanced', 'module', 'm04-findings-and-root-causes', 1, 'canCloseFinding is asked to close ISF-2026-005, a Minor nonconformity with status Open. Its action ac3 is Corrective and Open. Which requirement refuses it?', '["The open action: ac3 is still Open against the finding.", "The effectiveness check a Minor nonconformity needs before it closes.", "The correction: nothing records what was done about the thing that was found.", "The due date, 2026-12-11, which has not yet arrived."]'::jsonb, 2, 'The digest prints the correction refusal for ISF-2026-005: "Record the correction: what was done about the thing that was found. A corrective action deals with the cause, and this is the other half." The correction is the first thing the gate asks for.'),
  ('compliance', 'advanced', 'module', 'm04-findings-and-root-causes', 2, 'A Minor nonconformity has its correction recorded and no actions at all. What does canCloseFinding answer?', '["ALLOWED, because a Minor nonconformity closes on its correction alone.", "REFUSED until a corrective action is raised against the cause.", "REFUSED until its root cause is recorded, as for any nonconformity.", "ALLOWED only once an effectiveness check is recorded on the correction."]'::jsonb, 0, 'The digest prints: a Minor nonconformity with its correction and no actions: ALLOWED. isoCompliance.EFFECTIVENESS_REQUIRED_TYPES holds Major nonconformity alone, and the root cause refusal is written for a major nonconformity.'),
  ('compliance', 'advanced', 'module', 'm04-findings-and-root-causes', 3, 'On the Major nonconformity walk, the record holds a correction, a root cause and only a preventive action. Which requirement refuses it?', '["An effectiveness check on the preventive action, which has to be verified effective.", "A second root cause, written for the preventive action to address on its own.", "A due date, which a finding answered by a preventive action alone never carries.", "At least one action of type Corrective, which a preventive action cannot stand in for."]'::jsonb, 3, '"A major nonconformity needs at least one corrective action. A correction deals with the instance; a corrective action deals with the cause." A preventive action is welcome on a Major finding and does not satisfy the rule.'),
  ('compliance', 'advanced', 'module', 'm04-findings-and-root-causes', 4, 'A Major nonconformity''s corrective action is Complete, with no effectiveness check recorded. What does canCloseFinding answer?', '["ALLOWED, since Complete is the last status an action can reach on its own record.", "REFUSED, as a completed action is not yet one shown to work.", "REFUSED, asking for another corrective action to be raised in its place.", "ALLOWED, with a watch item on the readiness list until the check is recorded."]'::jsonb, 1, '"No corrective action has been verified effective yet. For a major nonconformity the effectiveness check is the point: a completed action is not a working one." The request for another action belongs to an action checked and found not to work.'),
  ('compliance', 'advanced', 'module', 'm04-findings-and-root-causes', 5, 'ISF-2026-004 holds ac1, Corrective, In progress, and ac4, Preventive, Complete and unchecked. Which refusal does it meet at 2026-10-15?', '["The root cause refusal, since ac4 was aimed at a cause nobody wrote down.", "The open action refusal, because ac1 is still open against it.", "The unchecked action refusal, since ac4 is Complete with no effectiveness verdict.", "The correction refusal, since a preventive action carries no correction."]'::jsonb, 1, 'The digest prints: "1 action still open against this finding." The refusal names the first thing missing on the walk, and ac1 is it.'),
  ('compliance', 'advanced', 'module', 'm04-findings-and-root-causes', 6, 'Suppose ac1 on ISF-2026-004 were completed and never checked. What would the record still lack before the finding could close?', '["a Complete action recorded against it", "a preventive action to sit beside ac1", "a due date recorded for the finding itself", "a corrective action verified effective"]'::jsonb, 3, 'ac4 is Preventive with verified effective false, and ac1 would be Complete and unchecked, so no corrective action would be verified effective. The finding already holds ac4, a preventive action that is Complete, and a due date, 2026-09-30.'),
  ('compliance', 'advanced', 'module', 'm04-findings-and-root-causes', 7, 'The register summary prints awaiting an effectiveness check 1. Which action is behind that count?', '["ac4, Preventive, on ISF-2026-004, Complete with no effectiveness verdict", "ac1, Corrective, on ISF-2026-004, In progress and past its due date", "ac2, Corrective, on ISF-2026-001, Complete and verified effective", "ac3, Corrective, on ISF-2026-005, Open with no verdict"]'::jsonb, 0, 'The digest names ac4 as the one Complete action with no effectiveness verdict recorded. ac1 and ac3 are still open, and ac2 reads verified effective true.'),
  ('compliance', 'advanced', 'module', 'm04-findings-and-root-causes', 8, 'Which root cause categories appear only in the ISO list?', '["Measurement or inspection, and Management system", "Measurement or inspection, on its own", "Measurement or monitoring, and Management system", "Measurement or monitoring, and Supplier or subcontractor"]'::jsonb, 2, 'isoCompliance.ROOT_CAUSE_CATEGORIES holds 10 and qualityAssurance.ROOT_CAUSE_CATEGORIES holds 9. Only in the quality list: Measurement or inspection. Supplier or subcontractor is in both.'),
  ('compliance', 'advanced', 'module', 'm04-findings-and-root-causes', 9, 'A Major nonconformity is raised in the Audit & Findings Manager. Which root cause list is its cause recorded against?', '["The quality list of 9, since the Audit & Findings Manager is a quality app.", "A list of its own, kept in step with the ISO list by a copy that is refreshed.", "The ISO list of 10, which auditManagement holds as the very same list object.", "The ISO list less Management system, a category kept for ISO registers."]'::jsonb, 2, 'The digest prints: auditManagement.ROOT_CAUSE_CATEGORIES is the same list object as isoCompliance''s: true. One list, so nothing can drift apart. auditManagement.canCloseFinding is the same function as isoCompliance''s as well.'),
  ('compliance', 'advanced', 'module', 'm04-findings-and-root-causes', 10, 'isoCompliance.isActionOverdue is the same function as qualityAssurance.isCapaOverdue. What follows?', '["An action is overdue by one rule, on an NCR or on a finding.", "A finding and an NCR close by one and the same rule.", "A CAPA on an NCR is counted in the ORASHI summary''s overdue actions.", "An action is overdue in the ISO register only once its finding is overdue."]'::jsonb, 0, 'Sharing isActionOverdue means an action''s lateness is read the same way in both apps. The function a finding closes by is canCloseFinding, which isoCompliance shares with auditManagement.'),
  ('compliance', 'advanced', 'module', 'm04-findings-and-root-causes', 11, 'The as-of date moves one month later. Which ORASHI findings then print a different age?', '["All five, since the age of every finding runs up to the as-of date it is read at", "ISF-2026-001 and ISF-2026-002, the two findings that are closed or voided", "ISF-2026-004 alone, as the one finding that reads overdue", "ISF-2026-004, ISF-2026-005 and ISF-2026-003, the three that are open"]'::jsonb, 3, 'The three open findings were raised 2026-06-12 and read 125 at 2026-10-15; each grows as the as-of date moves. ISF-2026-001 stopped at its closure, 2026-04-21, and ISF-2026-002 at 2026-06-13.'),
  ('compliance', 'advanced', 'module', 'm04-findings-and-root-causes', 12, 'ISF-2026-002, an Observation, was Voided and its age reads 3. Where does that age stop?', '["At the as-of date, since voiding a finding does not close it, so it keeps on ageing.", "At 2026-06-13, the date in its closed column, as a closed finding''s would.", "At its due date, which a voided finding keeps on its record.", "At the date its audit ended, which the findings table takes over."]'::jsonb, 1, 'ISF-2026-002 was raised 2026-06-10 and its closed column reads 2026-06-13. A voided finding stops ageing at the date it was voided, in the column a closed finding uses. Its due date reads none.'),
  ('compliance', 'advanced', 'module', 'm04-findings-and-root-causes', 13, 'ISF-2026-003 is an open Opportunity for improvement with no due date. What does its overdue flag read?', '["false, as a finding with no due date cannot fall overdue", "true, since its raised date stands in for the missing due date", "true, since every open finding raised 2026-06-12 reads overdue", "no value, and the summary counts it among findings overdue"]'::jsonb, 0, 'The raised date stands in for a missing due date only when findingByUrgency sorts. The summary prints findings overdue 1, and that finding is ISF-2026-004, due 2026-09-30.'),
  ('compliance', 'advanced', 'module', 'm04-findings-and-root-causes', 14, 'ISA-2026-001 is Reported with a planned end of 2026-06-12, and ISA-2026-002 is In progress with a planned end of 2026-10-09. Which reads overdue at 2026-10-15?', '["Both, since both planned ends are past the as-of date and both audits are open", "ISA-2026-001 alone, being the one that is further past its planned end", "ISA-2026-002 alone, since an audit is overdue only while undelivered", "Neither, since an open audit is never overdue in the ISO module"]'::jsonb, 2, 'isAuditOverdue reads Reported false and In progress true, in both modules. isoCompliance.AUDIT_UNDELIVERED_STATUSES holds Planned, In progress and Fieldwork complete. Both audits read open true.'),
  ('compliance', 'advanced', 'module', 'm04-findings-and-root-causes', 15, 'findingByUrgency places ISF-2026-003, an Opportunity for improvement, before ISF-2026-005, a Minor nonconformity. Why?', '["The rule ranks an Opportunity for improvement above a Minor nonconformity in its own right.", "Both rank 3, and 003 sorts by its raised date, 2026-06-12, which falls before 005''s due date, 2026-12-11.", "ISF-2026-005 is still waiting on its correction, and a refused finding drops below the others.", "ISF-2026-003 has no due date, and a finding with no due date always sorts ahead of the rest."]'::jsonb, 1, 'Only a Major nonconformity has ranks of its own, 0 and 1. Within a rank the earlier due date comes first, the raised date standing in for a missing one. The same rule puts ISF-2026-001 fourth and ISF-2026-002 fifth at rank 4.'),
  ('compliance', 'advanced', 'module', 'm05-certification-readiness', 1, 'certificationReadiness for ISO 14001:2015 at ORASHI returns ready false. What else does it return?', '["A readiness percentage weighted by severity, with the items that pulled it down.", "A single blocking reason, the first requirement that fails, as the earlier gates do.", "A score for each clause, with the certificate as a gate the rest of the list sits behind.", "A list of items, each with a severity, a count and a sentence, and a table of counts."]'::jsonb, 3, 'The list has eleven items across blocking, serious and watch, and a table of counts beside it. The digest prints no percentage and no score for it, and ready false stands beside four blocking items.'),
  ('compliance', 'advanced', 'module', 'm05-certification-readiness', 2, 'Under which severity does the item "3 applicable clauses have never been examined by an internal audit." sit?', '["serious, beside the clause last audited before this cycle began", "blocking, beside the open major nonconformity", "watch, beside the clause review that is past due", "serious, beside the one clause never assessed at all"]'::jsonb, 1, 'The four blocking items are the open major nonconformity, the 3 never examined clauses, the conformant clause with no evidence reference and the clause assessed nonconformant. The stale clause and the unassessed clause are serious.'),
  ('compliance', 'advanced', 'module', 'm05-certification-readiness', 3, 'ac1 is Corrective, In progress, due 2026-10-02, and reads overdue true. How does the readiness list carry it?', '["As a serious item: 1 corrective or preventive action is past its due date.", "As a watch item, beside the finding on the same Major that is past its due date.", "As a blocking item, being the corrective action on the open Major nonconformity.", "Not at all, since the open Major nonconformity already stands for it on the list."]'::jsonb, 0, 'The serious items are the stale clause, the clause never assessed and the overdue action. "1 finding is past its due date." is a watch item, and it is ISF-2026-004.'),
  ('compliance', 'advanced', 'module', 'm05-certification-readiness', 4, 'The certificate expiry is moved to 2026-10-14 and nothing else changes. What does the certificate item become?', '["A watch item saying the certificate expires today and the audit should be booked now.", "A blocking item, because an expired certificate stops the rest of the list behind it.", "A serious item: the certificate expired 1 day ago, and a recertification audit is needed.", "No item at all, because certificateExpiring reads false once the date has passed."]'::jsonb, 2, 'At certificateDays -1 the item reads: "The certificate expired 1 day ago. The organization cannot claim certification, and a surveillance audit is no longer possible: it needs a recertification audit." certificateExpired reads true.'),
  ('compliance', 'advanced', 'module', 'm05-certification-readiness', 5, 'Reading the edge table from a certificate far from expiry towards expiry, at which expiry date does the certificate item first appear?', '["2027-01-13, at certificateDays 90, as a watch item", "2027-01-14, at certificateDays 91, as the watch item", "2026-10-15, at certificateDays 0, as a watch item", "2026-10-14, at certificateDays -1, as a serious item"]'::jsonb, 0, 'isoCompliance.CERTIFICATE_LEAD_DAYS is 90. At 91 days the row prints certificateExpiring false and no item; at 90 the watch item appears.'),
  ('compliance', 'advanced', 'module', 'm05-certification-readiness', 6, 'The expiry is moved to 2026-10-15, the as-of date itself. What do the two certificate flags read?', '["certificateExpiring false and certificateExpired true, once the expiry date is reached", "both flags true, since the certificate both expires and is still expiring on that day", "certificateExpiring true, with certificateExpired false, on the expiry date itself", "both flags false, until the expiry date has fully passed"]'::jsonb, 2, 'certificateDays reads 0 and the watch item reads "The certificate expires today. Book the recertification audit now." The today in it is the as-of date the engine was given.'),
  ('compliance', 'advanced', 'module', 'm05-certification-readiness', 7, 'The certificate expiry is recorded as the text tbc. What does the readiness list say about the certificate?', '["A serious item, because an expiry that cannot be read is treated as expired.", "Nothing: certificateDays reads null, both flags read false and no item is listed.", "A watch item asking for the expiry date to be recorded before the audit.", "A blocking item, since readiness cannot be judged without an expiry date."]'::jsonb, 1, 'The rows for tbc and for null both print certificateDays null, certificateExpiring false, certificateExpired false and no item. An empty certificate line can mean the date is missing, and a reader has to know that.'),
  ('compliance', 'advanced', 'module', 'm05-certification-readiness', 8, 'Which record appears on the list under both blocking and watch?', '["Clause 4.3, as a clause never examined and as the clause review past its due date", "Clause 7.2, as the unevidenced claim and as the clause never assessed at all", "ac1, as the overdue action and as the finding that is past its due date", "ISF-2026-004, as the open major nonconformity and as the finding past its due date"]'::jsonb, 3, 'Clause 4.3 raises the serious stale item and the watch review item. Clause 7.2 raises the blocking never-examined item and the serious never-assessed item. Each item asks a separate question, and one record can fail more than one.'),
  ('compliance', 'advanced', 'module', 'm05-certification-readiness', 9, 'Clause 4.3 raises two items at 2026-10-15. Which two?', '["last audited before this cycle began, serious; its review past due, watch", "never examined by an internal audit, blocking; and its review past due, watch", "last audited before this cycle began, blocking; conformant without evidence, blocking", "its review past due, serious; a finding past its due date, watch"]'::jsonb, 0, 'Clause 4.3 reads stale true, last examined 2023-09-20, and review overdue true, next review 2026-10-01. Its evidence record reads true, so the unevidenced item is clause 5.2.'),
  ('compliance', 'advanced', 'module', 'm05-certification-readiness', 10, 'The blocking item "1 clause is marked conformant with no evidence reference recorded." points at which record, and what does that record lack?', '["Clause 7.5.3, which lacks an internal audit examination and already has its evidence", "Clause 5.2, which lacks its evidence reference and has its date and assessor", "Clause 6.1.3, which lacks an evidence reference and reads Nonconformant in the register", "Clause 7.2, which lacks evidence, a date and an assessor, and reads Not assessed"]'::jsonb, 1, 'missingEvidenceParts for 5.2 prints evidence reference, and its row reads assessed true and evidence record false. The readiness sentence names the part the claim lacks.'),
  ('compliance', 'advanced', 'module', 'm05-certification-readiness', 11, 'A standard with no clauses in the register is passed to certificationReadiness. What comes back?', '["ready true, since no item on the list carries a count above 0", "no answer, the call refusing until at least one clause is added", "ready false, with one blocking item of count 0 saying there is nothing to be ready with", "ready false, with one watch item asking for clauses to be registered"]'::jsonb, 2, '"This standard has no applicable clauses in the register yet, so there is nothing to be ready with." The engine does not let the absence of problems pass for readiness when there is nothing to have problems with.'),
  ('compliance', 'advanced', 'module', 'm05-certification-readiness', 12, 'The summary prints open findings 3, and the readiness counts print openMajor 1 and openMinor 1. Which open finding sits in the first count and in neither of the other two?', '["ISF-2026-002, the Observation that was voided on 2026-06-13", "ISF-2026-001, the Major nonconformity closed on 2026-04-21", "ISF-2026-005, the open Minor nonconformity", "ISF-2026-003, the open Opportunity for improvement"]'::jsonb, 3, 'The three open findings are ISF-2026-004, ISF-2026-005 and ISF-2026-003. openMajor counts ISF-2026-004 and openMinor ISF-2026-005. ISF-2026-001 and ISF-2026-002 read open false.'),
  ('compliance', 'advanced', 'module', 'm05-certification-readiness', 13, 'The summary prints audits open 2 and audits overdue 1. Which audit is open and not overdue?', '["ISA-2026-002, In progress, planned end 2026-10-09", "ISA-2026-001, Reported, since a Reported audit is delivered", "ISA-2025-003, Cancelled, since a cancelled audit stays open to the end", "ISA-2026-S01, as only Internal audits fall overdue"]'::jsonb, 1, 'ISA-2026-001 reads open true and overdue false; ISA-2026-002 reads open true and overdue true. The other four read open false.'),
  ('compliance', 'advanced', 'module', 'm05-certification-readiness', 14, 'A report wants to state ORASHI''s readiness from covered 8 and applicable 12. What does this module ask of it?', '["Quote both counts and the list items beside them, and form no fraction or percentage.", "Quote a percentage covered, rounded half up on the exact fraction as the engine does it.", "Quote covered on its own, since applicable follows from the certification cycle.", "Quote covered less the stale clause, as the effective coverage of the register."]'::jsonb, 0, 'The digest prints no percentage from these counts and neither does the engine. The list already says 3 uncovered clauses are never examined and blocking and 1 is stale and serious; a percentage would average that away.'),
  ('compliance', 'advanced', 'module', 'm05-certification-readiness', 15, 'The readiness counts print partial 1 and nonconformant 1. Which clause is behind each?', '["6.1.3 is the partial clause and 6.1.2 the nonconformant one", "5.2 is the partial clause and 6.1.3 the nonconformant one", "6.1.2 is the partial clause and 6.1.3 the nonconformant one", "6.1.2 is the partial clause and 7.2 the nonconformant one"]'::jsonb, 2, 'Clause 6.1.2 reads Partially conformant and clause 6.1.3 reads Nonconformant. Clause 5.2 reads Conformant without its evidence reference, and clause 7.2 reads Not assessed, behind notAssessed 1.'),
  ('compliance', 'advanced', 'module', 'm06-the-expert-reading', 1, 'ISA-2026-002 examined clause 5.2 on 2026-10-06, and 5.2''s last examined date does not move. Which owner decision is at work?', '["Q5: every examiner is checked for independence.", "Q4: ISO coverage counts only Reported or Closed audits.", "Q11: a cancellation without a reason does not complete a programme.", "Q2: evidence counts towards Compliant only for the current period."]'::jsonb, 1, 'ISA-2026-002 is In progress, so none of its results moves a clause''s date until it is reported. Q5 is module 2''s rule, Q11 the Professional tier''s, and Q2 the Associate tier''s.'),
  ('compliance', 'advanced', 'module', 'm06-the-expert-reading', 2, 'Which of these is an owner ambiguity, recorded in the FINDINGS files and left unchanged?', '["An expired certificate is a serious readiness item.", "Evidence counts towards Compliant only for the current period.", "A document review task is decided by its assigned reviewer, never by the author.", "nextReviewDate returns no date when the review period is missing."]'::jsonb, 3, 'The missing review period is one of the four owner ambiguities: the default of DEFAULT_REVIEW_PERIOD_MONTHS is the caller''s to apply. The other three are owner decisions in force: Q6, Q2 and D1.'),
  ('compliance', 'advanced', 'module', 'm06-the-expert-reading', 3, 'An audit programme is complete and one of its audits was cancelled with a written reason. How does its delivered percent read?', '["Below one hundred percent, by design, since it counts reported audits only.", "One hundred percent, since a cancellation with a reason completes the programme.", "No percent at all, since the programme refuses to print one while an audit is cancelled.", "As though the cancelled audit had never been planned."]'::jsonb, 0, 'A cancellation with its reason lets the programme complete under Q11, and delivery still counts reported audits only. The owner recorded this as an ambiguity and left it unchanged.'),
  ('compliance', 'advanced', 'module', 'm06-the-expert-reading', 4, 'A templated audit is passed with no checklist items. How does the unanswered-items rule treat it?', '["It refuses, as there is nothing to report.", "It passes only once each missing item is answered Not applicable with a reason.", "It passes vacuously, and the database counts the template itself.", "It reads as nothing answered of nothing and prints a progress of zero percent."]'::jsonb, 2, 'This is a held limit. The refusal about an audit that examined nothing belongs to canReportAudit in the ISO module, for an audit with no clauses in its scope.'),
  ('compliance', 'advanced', 'module', 'm06-the-expert-reading', 5, 'An unreadable today is passed to complianceStatus and to two other modules. Which of them refuses?', '["complianceStatus alone; the other two answer as though nothing were due.", "All three, since owner decision Q1 makes every module throw on an unreadable date.", "None, since each module reads the machine clock instead.", "isoCompliance alone, reading the most dates against today."]'::jsonb, 0, 'Q1 makes deriveStatus throw. The held limit is that the other two modules answer as though nothing were due, so an app that shows no overdue review has told you nothing if its date could not be read.'),
  ('compliance', 'advanced', 'module', 'm06-the-expert-reading', 6, 'Rule R1 is measured on four audits, one of them cancelled with no reason. How many outstanding do programmeProgress and summarise count?', '["1 in programmeProgress and 2 in summarise, which read the cancellation differently", "2 in each, since a cancellation without a written reason is outstanding in both", "2 in programmeProgress and 1 in summarise, which leaves the cancellation out", "3 in each, since a cancelled audit is outstanding with or without its reason"]'::jsonb, 1, 'R1 is one rule for outstanding: a cancellation without a written reason is outstanding in both, and canCompleteProgramme asks the same rule.'),
  ('compliance', 'advanced', 'module', 'm06-the-expert-reading', 7, 'Rule R2 governs every percent the engine prints. What does it state?', '["A percent is cut to a whole number, so a half never rounds up.", "A percent rounds half to even, as float arithmetic tends to.", "A percent is rounded from the one-decimal figure the app shows.", "A percent rounds half up, on the exact fraction."]'::jsonb, 3, 'checklistProgress, programmeProgress and planProgress are the three exports that print a percent, and each rounds half up on the exact fraction.'),
  ('compliance', 'advanced', 'module', 'm06-the-expert-reading', 8, 'Which of the ASC-0 rules is measured on the reason REG-2026-006 gives?', '["R1, one rule for outstanding", "R3, expired and expiring kept apart", "R4, a filed One-off says it is discharged", "R5, the register''s own standard named"]'::jsonb, 2, 'R4 is measured on REG-2026-006, which reads Compliant with a reason saying nothing further is due. R1 is measured on four audits, R3 on a certificate at certificateDays -15 and R5 on the ORASHI readiness list.'),
  ('compliance', 'advanced', 'module', 'm06-the-expert-reading', 9, 'Rule R5 is measured on the ORASHI readiness list. What does it print?', '["1 item naming ISO 14001:2015, and 0 naming ISO 9001", "0 items naming either, since readiness sentences name no standard", "1 item naming each standard", "11 items naming ISO 14001:2015, one for each item on the list"]'::jsonb, 0, 'R5: a sentence names the register''s own standard. The one item that names a standard is the blocking never-examined item, which cites ISO 14001:2015 §9.2.'),
  ('compliance', 'advanced', 'module', 'm06-the-expert-reading', 10, 'What do the oracles check about a gate, and what do they leave unchecked?', '["They check the wording of each refusal, sentence by sentence, against a golden copy.", "They check the verdict and the wording both, for gates that name a standard.", "They check the verdict, allowed or refused, and never the wording of its reason.", "They check neither, leaving gates to the app screens that display them."]'::jsonb, 2, 'Every refusal sentence in the digest is the engine''s own and is quoted rather than checked. That is why this course quotes a refusal verbatim or describes it, and never rewords one inside quotation marks.'),
  ('compliance', 'advanced', 'module', 'm06-the-expert-reading', 11, 'Which module''s oracle carries the most golden cases?', '["isoCompliance, with 235 cases", "qualityAssurance, with 422", "auditManagement, with 181 cases", "complianceStatus, with 171 cases"]'::jsonb, 1, 'The table prints qualityAssurance 422, isoCompliance 235, auditManagement 181, complianceStatus 171 and documentControl 130. Each golden file is written by an independent stdlib Python oracle.'),
  ('compliance', 'advanced', 'module', 'm06-the-expert-reading', 12, 'For isoCompliance, what does the oracle section print about exported functions without a case, and about its lists and constants?', '["0 functions without a case, and 0 lists without one, since every list has a golden case.", "1 function without a case, the sort, since a sort case is counted apart from the rest.", "25 functions without a case, one for each list or constant the module exports.", "0 functions without a case; its 25 lists and constants are data and carry no case of their own."]'::jsonb, 3, 'Every one of the six modules reads 0 without a case, a sort case counting for the sort it names. Lists and constants are data rather than functions. isoCompliance carries 1 sort case.'),
  ('compliance', 'advanced', 'module', 'm06-the-expert-reading', 13, 'Traced through every table in this tier, which readiness items does clause 7.2 raise?', '["Two: the blocking item for clauses no internal audit has examined, and the serious item for the unassessed clause.", "One: the unevidenced claim, blocking, because its evidence record reads false.", "Two: a stale coverage outcome, serious, and a clause review past due, watch.", "Three: never examined, never assessed, and its review due soon as a watch item."]'::jsonb, 0, 'Clause 7.2 reads Not assessed with claims conformity false, so it is no unevidenced claim, and it reads never in the coverage table. Its next review, 2027-01-31, raises neither review flag.'),
  ('compliance', 'advanced', 'module', 'm06-the-expert-reading', 14, 'A finding describes a risk someone wants scored, banded and set against appetite. Where does that question go?', '["To the readiness list, which bands each finding by severity.", "To findingByUrgency, whose ranks from 0 to 4 are the risk bands.", "To riskchange, which owns risk scores, bands, appetite and heat maps.", "To the root cause list, whose Management system entry scores risk."]'::jsonb, 2, 'A finding can feed a risk register or a lesson learned, and that is where the sibling course begins. Scores, bands, appetite and heat maps are taught there.'),
  ('compliance', 'advanced', 'module', 'm06-the-expert-reading', 15, 'Which of the AS15 owner decisions belong to the Associate tier?', '["Q4, Q5 and Q6 together", "Q1, Q2 and D1", "Q11 on its own", "Q1, Q4 and Q11"]'::jsonb, 1, 'Q1 is the unreadable today, Q2 current-period evidence and D1 the document reviewer. Q4, Q5 and Q6 are this tier''s modules 3, 2 and 5, and Q11 belongs to the Professional tier.'),
  ('compliance', 'advanced', 'final', null, 1, 'Which single addition to the ORASHI record would clear the blocking item about a clause marked conformant with no evidence reference?', '["An assessor''s name recorded on clause 6.1.3", "An internal audit examination of clause 7.5.3", "An evidence reference recorded on clause 5.2", "A written justification recorded on clause 4.4"]'::jsonb, 2, 'Clause 5.2 claims conformity with its evidence record false, and missingEvidenceParts prints evidence reference for it. Its date and assessor are already there, since it reads assessed true.'),
  ('compliance', 'advanced', 'final', null, 2, 'An assessor finds clause 7.2 failing and has no document to point to. Can the verdict go on the register?', '["Yes: Nonconformant with a date and an assessor is allowed with no evidence reference.", "No: every clause verdict needs evidence, a date and an assessor before it stands.", "Only as Partially conformant, which asks for less on the record than Nonconformant.", "Only once an audit finding has been raised and recorded against the clause."]'::jsonb, 0, 'The digest prints Nonconformant with a date and an assessor: ALLOWED. Partially conformant asks for all three, as Conformant does. A problem needs less on the record than a claim of conformity.'),
  ('compliance', 'advanced', 'final', null, 3, 'An ISO 45001:2018 register sets a clause to Not applicable on both fields and gives no reason. What does the refusal name?', '["§4.3 of ISO 45001:2018, as the ISO 9001:2015 sentence cites its own clause", "No standard at all, since only ISO 9001:2015 is ever named in the refusal", "ISO 14001:2015, as the standard the ORASHI register itself is kept against", "ISO 45001:2018, in the shape of the ISO 14001:2015 sentence"]'::jsonb, 3, '"Say why this requirement of ISO 45001:2018 does not apply. A requirement determined not applicable keeps its justification on record." Rule R5: a sentence names the register''s own standard.'),
  ('compliance', 'advanced', 'final', null, 4, 'Clause 7.5.3 carries evidence, a date and an assessor behind its Conformant status. Which gate did it pass, and which count still leaves it out?', '["It passed canSetClauseStatus, and coverage still reads it never examined.", "It passed the lead auditor check, and the evidenced count still leaves it out.", "It passed canReportAudit, and the conformant count still leaves it out.", "It passed canSetClauseStatus, and the evidenced count leaves it out."]'::jsonb, 0, 'The register verdict is the owner''s assessment; coverage asks whether a counting internal audit examined the clause. ISA-2025-003 examined 7.5.3 on 2025-11-12 and was Cancelled, so it reads never.'),
  ('compliance', 'advanced', 'final', null, 5, 'At 2026-10-15, which ORASHI clause reads review overdue true?', '["6.1.2, next review 2026-11-02, 18 days from the as-of date", "7.2, next review 2027-01-31, still Not assessed", "4.3, next review 2026-10-01, -14 days from the as-of date", "6.1.3, next review 2027-06-12, 240 days from the as-of date"]'::jsonb, 2, 'Clause 4.3 is the one row with a review date behind the as-of date. 6.1.2 reads review due soon true, and 7.2 and 6.1.3 read both flags false. The summary prints reviews overdue 1.'),
  ('compliance', 'advanced', 'final', null, 6, 'Who may lead the planned internal audit over 8.1, 8.2, 9.1.1 and 9.2 with the scope left as it is?', '["u-tari, whose one clause in the scope is Conformant", "u-nneka, since clause 9.2 is the internal audit clause", "u-chidi, or an external lead auditor named in text", "u-kalu, once another examiner records 8.1 and 8.2"]'::jsonb, 2, 'Both of those rows read ALLOWED. u-tari owns 9.1.1, u-nneka 9.2 and u-kalu 8.1 and 8.2, and each is refused for owning a clause in the scope, whatever that clause''s status.'),
  ('compliance', 'advanced', 'final', null, 7, 'The planner drops 8.1 and 8.2 from the planned audit''s scope so that u-kalu can lead it. What happens to clause 8.1''s coverage row?', '["Nothing moves: 8.1 keeps last examined 2024-05-16 from ISA-2024-001, since a planned audit does not count.", "8.1 reads never, because a clause taken out of an audit''s scope loses its examination history.", "8.1 reads stale, because a clause dropped from a planned scope lapses to before the cycle.", "8.1 reads covered by the new audit as soon as it is planned, whether or not it is in scope."]'::jsonb, 0, 'Coverage reads the latest examination by a Reported or Closed internal audit, and Planned is neither. At a cycle of 3 years 8.1 reads covered true from ISA-2024-001. ISA-2026-002, In progress, shows the same: its 2026-10-06 examination of 5.2 moves no date.'),
  ('compliance', 'advanced', 'final', null, 8, 'A member of an audit team is refused by canExamineClause. What does that refusal ask for?', '["That the scope drop the clause the member owns before the audit starts.", "That another member of the audit records the result for that clause.", "That the lead auditor countersign the result before it is recorded.", "That the clause owner in the register be changed to somebody else first."]'::jsonb, 1, 'The examiner refusal ends "so somebody else on the audit has to record this result." It offers no change of scope; that remedy is the lead auditor refusal''s, together with a change of auditor.'),
  ('compliance', 'advanced', 'final', null, 9, 'Which of these pairings of an app with the name its independence check reads is correct?', '["Audit & Findings Manager: the lead auditor against the auditee", "Document Control: the reviewer against the owner of the clause", "ISO register: the lead auditor against the auditee of the audit", "Audit & Findings Manager: each examiner against the clause owner"]'::jsonb, 0, 'Three records, three names: clause owners for the ISO register, the auditee for the Audit & Findings Manager, the revision''s author for Document Control. u-adaeze, author of rev-0019-10, is refused as its reviewer.'),
  ('compliance', 'advanced', 'final', null, 10, 'The certification body''s surveillance audit examined clause 6.1.2 in 2026. Why is 6.1.2 still among the clauses never examined?', '["Its surveillance result was Conformant, and only a Nonconformant result counts as an examination.", "6.1.2 is Partially conformant, and coverage leaves out any clause without a full verdict recorded.", "Only Internal audits count, and no internal audit has examined 6.1.2.", "The surveillance audit is still waiting for its report, so its results do not count yet."]'::jsonb, 2, 'COVERING_AUDIT_TYPES holds the one word Internal. ISA-2026-S01 examined 6.1.2, Conformant on 2026-07-22, and the coverage row for 6.1.2 still reads last examined never, by audit none.'),
  ('compliance', 'advanced', 'final', null, 11, 'Which ORASHI audits count towards coverage?', '["ISA-2026-001 and ISA-2026-S01", "ISA-2026-001 and ISA-2026-002, the two still open", "All five of the Internal audits, whatever their status", "ISA-2023-002, ISA-2024-001 and ISA-2026-001"]'::jsonb, 3, 'Two Closed internal audits and one Reported one. ISA-2026-S01 fails on its type, ISA-2026-002 (In progress) and ISA-2025-003 (Cancelled) on their status.'),
  ('compliance', 'advanced', 'final', null, 12, 'What separates a stale clause from a never examined one?', '["A stale clause was examined by a Surveillance audit; a never examined clause by nobody at any time.", "A stale clause had a counting examination before the cycle began; a never examined clause had none at all.", "A stale clause failed its last examination; a never examined clause was not reached by its audit.", "A stale clause is past its review date; a never examined clause has no review date on the register."]'::jsonb, 1, 'Clause 4.3, last examined 2023-09-20, reads stale true. Clauses 6.1.2, 7.2 and 7.5.3 read never with stale false. The list ranks them apart: never examined blocking, stale serious.'),
  ('compliance', 'advanced', 'final', null, 13, 'A register mixes ISO 14001:2015 and ISO 45001:2018 clauses. Which call reads each clause against its own standard''s cycle?', '["clauseCoverage", "clauseCoverageByStandard", "certificationReadiness", "missingEvidenceParts"]'::jsonb, 1, 'clauseCoverage is run over the register at one cycle, 3 years, and again at 1, 2 and 4. clauseCoverageByStandard reads ISO 14001:2015 at 3 years and ISO 45001:2018 at 1 year, so two clauses last examined 2025-10-14 read covered and stale.'),
  ('compliance', 'advanced', 'final', null, 14, 'At a cycle of 1 year, what does the ORASHI coverage table print?', '["covered 8, stale 1, never examined 3", "covered 9, stale 0, never examined 3", "covered 6, stale 0, never examined 6", "covered 6, stale 3, never examined 3"]'::jsonb, 3, 'The rows read 1 year: 6, 3, 3; 2 years: 6, 3, 3; 3 years: 8, 1, 3; 4 years: 9, 0, 3. Never examined does not move with the cycle.'),
  ('compliance', 'advanced', 'final', null, 15, 'Clause 5.2''s latest counting result is an Observation. Does 5.2 read covered?', '["No: an Observation records a remark and is not a verdict on the clause.", "No: the clause stays uncovered until the observation is closed as a finding.", "Yes, though only once ISA-2026-002 reports its later Conformant result.", "Yes: the examination on 2026-06-09 is inside the cycle, whatever it found."]'::jsonb, 3, 'Coverage records that a counting audit looked at the clause inside the cycle, and the result is read elsewhere. An Observation on 5.2 and a Nonconformant result on 6.1.3 both read covered true.'),
  ('compliance', 'advanced', 'final', null, 16, 'Which ORASHI finding does canCloseFinding allow at 2026-10-15?', '["ISF-2026-005, which may close on its action ac3", "ISF-2026-001, which may close a second time", "ISF-2026-003, which may close with nothing more recorded", "ISF-2026-002, which may close again once voided"]'::jsonb, 2, 'ISF-2026-005 is refused for want of its correction, ISF-2026-004 for its open action, ISF-2026-001 as already closed and ISF-2026-002 as already voided. An Opportunity for improvement is no nonconformity.'),
  ('compliance', 'advanced', 'final', null, 17, 'A corrective action on a Major nonconformity is checked and found not to have worked. What does the engine ask for?', '["The correction recorded again, since the instance has come back.", "The root cause changed to Other, since the first cause was wrong.", "The finding downgraded to a Minor nonconformity so it can close.", "Another corrective action, raised in place of closing over the one that failed."]'::jsonb, 3, '"A corrective action here was checked and found not to have worked. Raise another one rather than closing over it." Only a corrective action verified effective closes a Major nonconformity.'),
  ('compliance', 'advanced', 'final', null, 18, 'On an NCR in the quality module, which record plays the part a correction plays on a finding?', '["The corrective action, which deals with the cause", "The root cause, which names the category of failure", "The effectiveness check, which proves the fix worked", "The disposition agreed on the nonconforming item"]'::jsonb, 3, 'The quality module pairs the two in its refusal: a disposition deals with the item and a corrective action with the cause. On a finding a correction deals with the instance, so the disposition is its counterpart on an NCR.'),
  ('compliance', 'advanced', 'final', null, 19, 'A cause recorded as Measurement or inspection on an NCR and one recorded as Measurement or monitoring on a finding: how should a reader count them?', '["As one category, since both of them describe a measurement failure.", "As the ISO category, since the quality list is a subset of the ISO list.", "As Other, since neither list holds the other list''s word for it.", "As two categories from two lists, each quoted in its own list''s words."]'::jsonb, 3, 'Measurement or inspection is only in the quality list of 9; Measurement or monitoring and Management system are only in the ISO list of 10. The quality list is no subset of the ISO list.'),
  ('compliance', 'advanced', 'final', null, 20, 'ISF-2026-001 was raised 2026-02-03 and closed 2026-04-21. What happens to its age as the as-of date moves later?', '["It grows by one each day, in the same way an open finding''s age grows.", "It resets to zero at closure.", "It grows until its due date, 2026-04-30.", "It stays fixed, since it answers how long the finding took to close."]'::jsonb, 3, 'A closed or voided finding stops ageing at its closed date. The three open findings, raised 2026-06-12, read 125 at 2026-10-15 and keep growing.'),
  ('compliance', 'advanced', 'final', null, 21, 'Which ORASHI finding sorts first in findingByUrgency, and at which rank?', '["ISF-2026-003 at rank 0, the open finding with the earliest raised date", "ISF-2026-001 at rank 1, the Major nonconformity raised earliest of all", "ISF-2026-004 at rank 0, an open Major nonconformity that is overdue", "ISF-2026-005 at rank 2, the open finding whose due date falls latest"]'::jsonb, 2, 'Rank 0 is an open Major nonconformity that is overdue, and ISF-2026-004, due 2026-09-30, is the only finding reading overdue true. ISF-2026-003 and ISF-2026-005 both rank 3, and ISF-2026-001 ranks 4.'),
  ('compliance', 'advanced', 'final', null, 22, 'An audit reads Fieldwork complete and its planned end has passed. Is it overdue?', '["No, as its fieldwork is done", "Yes, in both modules", "Only in auditManagement", "No, only Planned and In progress are"]'::jsonb, 1, 'isAuditOverdue reads Fieldwork complete true in isoCompliance and in auditManagement. AUDIT_UNDELIVERED_STATUSES holds Planned, In progress and Fieldwork complete; an audit is overdue only while it is undelivered.'),
  ('compliance', 'advanced', 'final', null, 23, 'A certificate has 91 days left to run. What do its two flags read, and what does the list carry for it?', '["Both flags false, and no certificate item on the list.", "certificateExpiring true, and a watch item on the list.", "certificateExpiring true, and no item on the list yet.", "Both flags false, and a watch item counting the days."]'::jsonb, 0, 'The lead window is 90 days, so a certificate one day beyond it raises neither flag. Moved one day nearer, to 2027-01-13, the row reads certificateExpiring true with a watch item.'),
  ('compliance', 'advanced', 'final', null, 24, 'A certificate reads certificateDays -15. Which flag reads true?', '["certificateExpiring alone, until the recertification audit is booked", "certificateExpired alone, since rule R3 keeps the two apart", "certificateExpired and certificateExpiring, both of them", "Neither flag, since certificateDays below 0 reads null"]'::jsonb, 1, 'Rule R3: expired and expiring are two separate flags, and a certificate at -15 reads certificateExpiring false and certificateExpired true. Under Q6 an expired certificate is a serious readiness item.'),
  ('compliance', 'advanced', 'final', null, 25, 'Which three items does the ORASHI readiness list rank serious?', '["the stale clause, the clause never assessed and the overdue action", "the open Major, the never examined clauses and the unevidenced claim", "the minor nonconformity, the past-due review and the overdue finding", "the stale clause, the overdue finding and the certificate item"]'::jsonb, 0, 'The serious items read: 1 clause last audited before this certification cycle began, 1 applicable clause never assessed, and 1 corrective or preventive action past its due date.'),
  ('compliance', 'advanced', 'final', null, 26, 'Of the four blocking items on the ORASHI readiness list, which one comes from a finding?', '["The item counting each Major finding still open", "The clauses never examined by an internal audit", "The clause marked conformant with no evidence reference", "The clause assessed nonconformant and not yet resolved"]'::jsonb, 0, '"1 major nonconformity is open. A certification body will not recommend certification over one." ISF-2026-004 is the one open Major. The other three blocking items count clauses: 3 never examined, 5.2 without its evidence reference and 6.1.3 assessed nonconformant.'),
  ('compliance', 'advanced', 'final', null, 27, 'The watch item "1 minor nonconformity is open." stands on the ORASHI list. Which finding is behind it, and what keeps that finding from closing?', '["ISF-2026-003, with an action still open", "ISF-2026-005, which has no correction recorded yet", "ISF-2026-004, which has no corrective action verified effective", "ISF-2026-002, which was voided before its correction was recorded"]'::jsonb, 1, 'openMinor 1 is ISF-2026-005, due 2026-12-11. canCloseFinding refuses it with the correction sentence: "Record the correction: what was done about the thing that was found." ISF-2026-004 is the open Major, a blocking item.'),
  ('compliance', 'advanced', 'final', null, 28, 'The blocking item for never-examined clauses cites which requirement?', '["ISO 14001:2015 §9.2: the organization audits its own system", "ISO 19011, which bars an auditor from auditing their own work", "ISO 9001:2015 §4.3, which keeps a justification for an exclusion", "ISO 14001:2015 §9.2, which calls for certification body surveillance"]'::jsonb, 0, '"3 applicable clauses have never been examined by an internal audit. ISO 14001:2015 §9.2 requires the organization to audit its own system." COVERING_AUDIT_TYPES holds Internal alone, so a surveillance audit moves no clause''s date.'),
  ('compliance', 'advanced', 'final', null, 29, 'Which readiness count and summary count print the same figure for the same thing under two names?', '["openMajor 1 and open findings 3", "evidenced 9 and unevidenced claims 1", "covered 8 and clauses covered 8", "staleAudited 1 and reviews overdue 1"]'::jsonb, 2, 'Never audited 3 and neverAudited 3 are another such pair. staleAudited 1 is clause 4.3''s coverage and reviews overdue 1 is clause 4.3''s review: equal figures, two different counts.'),
  ('compliance', 'advanced', 'final', null, 30, 'Owner decisions Q4, Q5 and Q6 each show up in one module of this tier. Which pairing is right?', '["Q4 independence, Q5 coverage, Q6 findings", "Q4 findings, Q5 coverage, Q6 the claim register", "Q4 coverage, Q5 independence, Q6 readiness", "Q4 readiness, Q5 findings, Q6 independence"]'::jsonb, 2, 'Q4: ISO coverage counts only Reported or Closed audits. Q5: every examiner is checked for independence. Q6: an expired certificate is a serious readiness item, one inside the lead window a watch item.'),
  ('compliance', 'advanced', 'final', null, 31, 'An app shows no overdue review for a document. Which held limit should stop a reader taking that at face value?', '["A templated audit with no checklist items passes the unanswered-items rule vacuously.", "A complete programme containing a cancelled audit reads below one hundred percent.", "A missing review period makes nextReviewDate return a date 24 months after issue.", "An unreadable today is refused in one module only, so a clean screen elsewhere proves nothing."]'::jsonb, 3, 'Of the four held limits this is the one a screen hides: an empty overdue list looks the same whether today was read or not. The other three concern a missing review period, a templated audit and a programme with a cancelled audit.'),
  ('compliance', 'advanced', 'final', null, 32, 'Rule R1 puts one rule behind three exports. What does that rule decide?', '["Whether an audit is outstanding, for programmeProgress, summarise and canCompleteProgramme alike", "Whether an audit is overdue, for isoCompliance and auditManagement alike", "Whether a percent rounds up, for each of the three exports that print one", "Whether a sentence names its standard, for every refusal that is returned"]'::jsonb, 0, 'On four audits with one cancelled and no reason, programmeProgress counts 2 outstanding and summarise counts 2. The overdue rule for audits is the ASC-1 rule, a separate one.'),
  ('compliance', 'advanced', 'final', null, 33, 'An obligation with no lead time set reads Due soon. What does its reason say?', '["That it is inside the default lead time, and that none is set for this obligation.", "That it is due soon, with nothing said about which lead time was applied.", "That a lead time must be recorded before any status can be derived.", "That it reads On track, since only a recorded lead time starts Due soon."]'::jsonb, 0, 'The ASC-1 rule: the Due soon reason says when the default lead time applies, as REG-2026-012''s reason does. complianceStatus.DEFAULT_LEAD_TIME_DAYS is the default it names.'),
  ('compliance', 'advanced', 'final', null, 34, 'A golden figure sits beside an engine figure and the two agree. What has that shown?', '["That the engine was run twice with one result.", "Two methods agreeing, one of them an independent Python oracle.", "That the refusal sentence beside the figure is correct word for word.", "That the figure matches a published standard''s own worked example."]'::jsonb, 1, 'Each golden file is written by an independent stdlib Python oracle from the rules as the modules and the status document state them. The oracles check a gate''s verdict and never its wording.'),
  ('compliance', 'advanced', 'final', null, 35, 'The oracle table gives sort cases a column of their own. Which module''s golden file carries 3 of them?', '["qualityAssurance, of 422 golden cases", "auditManagement, of 181 golden cases", "complianceStatus, of 171 golden cases", "documentControl, of 130 golden cases"]'::jsonb, 2, 'The sort cases column reads complianceStatus 3, documentControl 2, qualityAssurance 2, auditManagement 2, isoCompliance 1 and calendar 0. A sort case counts as a case for the sort it names.'),
  ('compliance', 'advanced', 'final', null, 36, 'Which of these does this course own?', '["Risk scores, risk bands and heat maps", "The Management of Change approval gates", "Audit independence and the root cause categories", "How a lesson learned is written and approved"]'::jsonb, 2, 'This course owns audit independence in both forms, the audit and finding lifecycles and the root cause categories. The other three belong to riskchange, "Risk, Change & Learning".'),
  ('compliance', 'advanced', 'final', null, 37, 'Clause 7.2 is set to Nonconformant with no date. What does canSetClauseStatus ask for?', '["The evidence, the date it was assessed and who assessed it.", "A date for the assessment and the assessor''s name.", "Why the requirement does not apply, kept on record.", "The applicability and the status set together."]'::jsonb, 1, 'The refusal reads "Record the date this was assessed and who assessed it." A Nonconformant verdict is allowed with no evidence reference. The sentence naming all three belongs to Conformant and Partially conformant requests.'),
  ('compliance', 'advanced', 'final', null, 38, 'Which clause does the serious item "1 clause was last audited before this certification cycle began." point at, and what was its last counting examination?', '["8.1, examined 2024-05-16 by ISA-2024-001", "4.3, examined 2023-09-20 by ISA-2023-002", "6.1.2, examined 2026-07-22 by ISA-2026-S01", "7.5.3, examined 2025-11-12 by ISA-2025-003"]'::jsonb, 1, 'Clause 4.3 reads stale true, at -1121 days. 8.1 is covered at 3 years, and 6.1.2 and 7.5.3 were examined only by audits that do not count, so both read never.'),
  ('compliance', 'advanced', 'final', null, 39, 'ac4 is Preventive, Complete, with no effectiveness verdict. Where does it show in the ORASHI counts?', '["In the summary''s awaiting an effectiveness check 1", "In the summary''s overdue actions 1, as its due date 2026-09-01 has passed", "In the summary''s open actions 2, counted beside ac1", "Nowhere, since a Complete action leaves every count"]'::jsonb, 0, 'The summary''s open actions 2 are ac1 and ac3, and overdue actions 1 is ac1. ac4 reads open false and overdue false, and the digest names it as the action awaiting an effectiveness check.'),
  ('compliance', 'advanced', 'final', null, 40, 'How does canCloseFinding in the Audit & Findings Manager relate to canCloseFinding in the ISO register?', '["The Audit & Findings Manager''s copy skips the effectiveness check on a Major.", "They agree on Majors and differ on Minors.", "The ISO version asks for an independent examiner before it closes a finding.", "They are one function, so a finding closes by one rule in both apps."]'::jsonb, 3, 'One function object serves both apps, so the Major walk, with its correction, root cause, corrective action and effectiveness check, is the same walk in each. isoCompliance.isActionOverdue is likewise the quality module''s isCapaOverdue.'),
  ('compliance', 'advanced', 'final', null, 41, 'What does rule R5 guarantee a reader of a refusal or of a readiness sentence?', '["That it cites a numbered clause of whichever standard it names.", "That it names the standard of the register it was read against.", "That the oracle has checked its wording word for word.", "That it names ISO 19011 whenever a person is refused."]'::jsonb, 1, 'The ORASHI list carries 1 item naming ISO 14001:2015 and 0 naming ISO 9001. Only the ISO 9001:2015 Not applicable refusal cites a numbered clause, §4.3.'),
  ('compliance', 'advanced', 'final', null, 42, 'Which one action on the record would remove the serious item about a clause never assessed at all?', '["Auditing clause 7.2 in an internal audit and reporting the audit that examined it", "Assessing clause 7.2 and recording a verdict that canSetClauseStatus allows", "Recording an evidence reference against clause 5.2 in the register", "Setting 7.2 to Not applicable while its applicability reads Applicable"]'::jsonb, 1, 'Clause 7.2 reads Not assessed, and notAssessed 1 is the count behind the serious item. An internal audit would clear its blocking never-examined item and leave the register verdict missing, and setting Not applicable with applicability unchanged is refused.');
